    val parts = path.split('.')
    extractPath(value, parts.toList).map(tokenize)
  }

  private def extractPath(current: JsonValue, parts: List[String]): Option[JsonValue] = parts match {
    case Nil => Some(current)
    case head :: tail =>
      current match {
        case JObject(fields) =>
          fields.get(head).flatMap(extractPath(_, tail))
        case JArray(values) =>
          Try(head.toInt).toOption.flatMap { idx =>
            if (idx >= 0 && idx < values.length) extractPath(values(idx), tail)
            else None
          }
        case _ => None
      }
  }

  private def jsonToString(value: JsonValue, indent: Int): String = {
    val nextIndent = if (indent >= 0) indent + 2 else -1

    value match {
      case JString(s) => s""""$s""""
      case JNumber(n) => n.toString
      case JBoolean(b) => b.toString
      case JNull => "null"
      case JArray(values) =>
        if (indent >= 0) {
          val items = values.map(v => " " * nextIndent + jsonToString(v, nextIndent))
          s"[\n${items.mkString(",\n")}\n${" " * indent}]"
        } else {
          values.map(jsonToString(_, -1)).mkString("[", ",", "]")
        }
      case JObject(fields) =>
        if (indent >= 0) {
          val items = fields.map { case (k, v) =>
            s"""${" " * nextIndent}"$k": ${jsonToString(v, nextIndent)}"""
          }
          s"{\n${items.mkString(",\n")}\n${" " * indent}}"
        } else {
          fields.map { case (k, v) => s""""$k":${jsonToString(v, -1)}""" }.mkString("{", ",", "}")
        }
