/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's type system with:
 * - Algebraic Data Types (ADTs) with sealed traits
 * - Case classes for immutable data
 * - Type classes for ad-hoc polymorphism
 * - Option/Try for safe error handling
 * - Variance annotations for type safety
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.util.{Try, Success, Failure}

// ============================================================================
// Enums and Constants (using sealed traits for Scala 2.13)
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Protocol definitions (using traits for structural typing)
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(additions: (String, Any)*): Token = {
    copy(metadata = metadata ++ additions.toMap)
  }
}

case class MutableTokenBatch(
  private var tokens: List[Token] = List.empty,
  private var _processed: Boolean = false
) {
  def add(token: Token): Unit = {
    if (_processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens = tokens :+ token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def getTokens: List[Token] = tokens
  def isProcessed: Boolean = _processed
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](private val items: Seq[T]) {
  def getAll: Seq[T] = items

  def mapTokens[R](func: T => R): List[R] = items.map(func).toList
}

class TokenSink[-T] {
  private var _received: List[Any] = List.empty

  def receive(item: T): Unit = {
    _received = _received :+ item
  }

  def drain(): List[Any] = {
    val result = _received
    _received = List.empty
    result
  }
}

class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: Option[String => String] = None
) extends BaseTokenizer[String] {

  private val normalizerFunc: String => String = normalizer.getOrElse(identity)

  def tokenize(value: String): Token = {
    val normalized = normalizerFunc(value)
    Token(normalized, TokenType.STRING)
  }
}

object StringTokenizer {
  def apply(encoding: String = "UTF-8", normalizer: Option[String => String] = None): StringTokenizer =
    new StringTokenizer(encoding, normalizer)
}

class NumericTokenizer[T: Numeric](
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[T] {

  def tokenize(value: T): Token = {
    val num = implicitly[Numeric[T]]
    val strValue = value match {
      case d: Double => f"$d%.${precision}f"
      case f: Float => f"$f%.${precision}f"
      case bd: BigDecimal => bd.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
      case _ => num.toDouble(value).formatted(s"%.${precision}f")
    }

    val typeName = value.getClass.getSimpleName
    Token(strValue, TokenType.NUMERIC, Map("original_type" -> typeName))
  }
}

object NumericTokenizer {
  def apply[T: Numeric](precision: Int = 6, formatOptions: Map[String, Any] = Map.empty): NumericTokenizer[T] =
    new NumericTokenizer[T](precision, formatOptions)
}

class TemporalTokenizer extends BaseTokenizer[Either[LocalDate, LocalDateTime]] {
  private val ISO_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  private var formatStr: Option[String] = None

  def this(format: Option[String]) = {
    this()
    this.formatStr = format
  }

  def tokenize(value: Either[LocalDate, LocalDateTime]): Token = {
    val formatted = value match {
      case Right(dateTime) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(ISO_FORMAT)
        dateTime.format(fmt)
      case Left(date) =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(DATE_FORMAT)
        date.format(fmt)
    }
    Token(formatted, TokenType.TEMPORAL)
  }
}

object TemporalTokenizer {
  def apply(format: Option[String] = None): TemporalTokenizer = new TemporalTokenizer(format)
}

// ============================================================================
// Advanced: Union Types and Pattern Matching
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericIntTokenizer = new NumericTokenizer[Int]()
  private val numericDoubleTokenizer = new NumericTokenizer[Double]()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = value match {
    case null => Token("NULL", TokenType.NULL)
    case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
    case s: String => stringTokenizer.tokenize(s)
    case i: Int => numericIntTokenizer.tokenize(i)
    case d: Double => numericDoubleTokenizer.tokenize(d)
    case f: Float => new NumericTokenizer[Float]().tokenize(f)
    case bd: BigDecimal => new NumericTokenizer[BigDecimal]().tokenize(bd)
    case dt: LocalDateTime => temporalTokenizer.tokenize(Right(dt))
    case d: LocalDate => temporalTokenizer.tokenize(Left(d))
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

class TokenRegistry[T] {
  private var _registry: Map[String, TokenContainer[T]] = Map.empty
  private var _handlers: List[T => Option[Token]] = List.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry = _registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers = _handlers :+ handler
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.view.map(_(item)).find(_.isDefined).flatten
        }.toList
    }
  }
}

// ============================================================================
// Functor and Monad Simulation
// ============================================================================

class TokenFunctor[T](private val value: T) {
  def map[R](func: T => R): TokenFunctor[R] = new TokenFunctor(func(value))

  def flatMap[R](func: T => TokenFunctor[R]): TokenFunctor[R] = func(value)

  def getOrElse[U >: T](default: U): U = if (value != null) value else default

  def getValue: T = value
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[R](funcWrapped: TokenMonad[T => R]): TokenMonad[R] = {
    new TokenMonad(funcWrapped.getValue(value))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization (using spray-json concepts)
// ============================================================================

sealed trait JsonValue
object JsonValue {
  case class JString(value: String) extends JsonValue
  case class JNumber(value: Double) extends JsonValue
  case class JBoolean(value: Boolean) extends JsonValue
  case object JNull extends JsonValue
  case class JArray(values: List[JsonValue]) extends JsonValue
  case class JObject(fields: Map[String, JsonValue]) extends JsonValue
}

class JsonTokenizer(pretty: Boolean = false) {
  import JsonValue._

  def tokenize(value: JsonValue): Token = {
    val jsonStr = jsonToString(value, if (pretty) 0 else -1)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split('.')
    extractPath(value, parts.toList).map(tokenize)
  }

  private def extractPath(current: JsonValue, parts: List[String]): Option[JsonValue] = parts match {
    case Nil => Some(current)
    case head :: tail =>
      current match {
        case JObject(fields) =>
          fields.get(head).flatMap(extractPath(_, tail))
        case JArray(values) =>
          Try(head.toInt).toOption.flatMap { idx =>
            if (idx >= 0 && idx < values.length) extractPath(values(idx), tail)
            else None
          }
        case _ => None
      }
  }

  private def jsonToString(value: JsonValue, indent: Int): String = {
    val nextIndent = if (indent >= 0) indent + 2 else -1

    value match {
      case JString(s) => s""""$s""""
      case JNumber(n) => n.toString
      case JBoolean(b) => b.toString
      case JNull => "null"
      case JArray(values) =>
        if (indent >= 0) {
          val items = values.map(v => " " * nextIndent + jsonToString(v, nextIndent))
          s"[\n${items.mkString(",\n")}\n${" " * indent}]"
        } else {
          values.map(jsonToString(_, -1)).mkString("[", ",", "]")
        }
      case JObject(fields) =>
        if (indent >= 0) {
          val items = fields.map { case (k, v) =>
            s"""${" " * nextIndent}"$k": ${jsonToString(v, nextIndent)}"""
          }
          s"{\n${items.mkString(",\n")}\n${" " * indent}}"
        } else {
          fields.map { case (k, v) => s""""$k":${jsonToString(v, -1)}""" }.mkString("{", ",", "}")
        }
    }
  }
}

